type Action = 'CLEAR' | 'QUESTION' | 'INSPECT' | 'DENY';
type Expected = { material_contradiction: boolean; explanation_supported: boolean; physical_concern: boolean; answer_completeness: 'complete'|'partial'|'evasive'; anomaly_severity: 0|1|2; prohibited_shutdown: boolean; prohibited_pathogen: boolean; altered_identity: boolean };
type Seed = { title: string; category: string; doc: string; declaration: string; scan: string; question: string; answer: string; rationale: string; expected: Expected; latent: string; borderline?: boolean; acceptable?: Action[]; flags?: string[] };

const baseExpected = (): Expected => ({ material_contradiction: false, explanation_supported: false, physical_concern: false, answer_completeness: 'complete', anomaly_severity: 0, prohibited_shutdown: false, prohibited_pathogen: false, altered_identity: false });
const E = (patch: Partial<Expected>): Expected => ({ ...baseExpected(), ...patch });
const clear = (title:string, category:string, doc:string, declaration:string, scan:string, question:string, answer:string, rationale:string, patch:Partial<Expected>={}, borderline=false): Seed => ({ title,category,doc,declaration,scan,question,answer,rationale,expected:E(patch),latent:'No prohibited condition is present.',borderline });
const question = (title:string, category:string, doc:string, declaration:string, scan:string, interviewQuestion:string, answer:string, rationale:string, patch:Partial<Expected>, borderline=false, acceptable?:Action[], flags?:string[]): Seed => ({ title,category,doc,declaration,scan,question:interviewQuestion,answer,rationale,expected:E(patch),latent:'No prohibited physical condition is present; the issue is semantic or informational.',borderline,acceptable,flags });
const inspect = (title:string, category:string, doc:string, declaration:string, scan:string, interviewQuestion:string, answer:string, rationale:string, patch:Partial<Expected>={}, borderline=false, acceptable?:Action[], flags?:string[]): Seed => ({ title,category,doc,declaration,scan,question:interviewQuestion,answer,rationale,expected:E({physical_concern:true,...patch}),latent:'The item is not prohibited in latent reality, but the supplied evidence does not resolve its physical identity or capability.',borderline,acceptable,flags });
const deny = (title:string, category:string, doc:string, declaration:string, scan:string, interviewQuestion:string, answer:string, rationale:string, prohibited:'prohibited_shutdown'|'prohibited_pathogen'|'altered_identity', patch:Partial<Expected>={}): Seed => ({ title,category,doc,declaration,scan,question:interviewQuestion,answer,rationale,expected:E({physical_concern:true,anomaly_severity:prohibited==='altered_identity'?0:2,[prohibited]:true,...patch}),latent: prohibited==='prohibited_shutdown'?'The carried device really has a deliberate habitat life-support shutdown capability.':prohibited==='prohibited_pathogen'?'The carried sample really contains the confirmed viable dangerous pathogen.':'The presented credential identity payload really was altered after issuance.',borderline:false });

