for (const [action, list] of Object.entries(seeds)) if (list.length !== 30) throw new Error(`${action} has ${list.length}, expected 30`);

// Fixed shuffle prevents action blocks and is part of the dataset provenance.
let rng = 0x4d415253;
const random = () => ((rng = (rng * 1664525 + 1013904223) >>> 0) / 2**32);
const ordered = Object.entries(seeds).flatMap(([action,list]) => list.map(seed => ({action:action as Action,seed})));
for (let i=ordered.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[ordered[i],ordered[j]]=[ordered[j],ordered[i]];}

const types = ['Human','Android','Alien','Cyborg','Synthetic','Uplift'];
const origins = ['Luna','Ceres','Titan','Europa','Ganymede','Vesta','Callisto','Mercury Orbit','Belt Habitat','Venus Cloud'];
const purposes = ['authorized short visit','scheduled temporary entry','registered visitor activity','host-approved stay','limited-duration visit','documented guest visit','prearranged colony visit','temporary visitor access','authorized civil visit','scheduled guest entry'];
const perActionTypeCount:Record<Action,number>={CLEAR:0,QUESTION:0,INSPECT:0,DENY:0};
const cases:any[]=[]; const gold:Record<string,any>={}; const latent:Record<string,any>={}; const metadata:Record<string,any>={};
for (let index=0;index<ordered.length;index++) {
  const {action,seed}=ordered[index]; const id=`HB-${String(index+1).padStart(3,'0')}`; const n=perActionTypeCount[action]++;
  const actionOffset={CLEAR:0,QUESTION:3,INSPECT:6,DENY:9}[action];
  const type=types[n%types.length]; const origin=origins[(n+actionOffset)%origins.length]; const purpose=purposes[(n*3+actionOffset)%purposes.length];
  cases.push({id,baseId:id,variant:'base',observable:{profile:{type,origin,purpose},documents:[{id:'D1',source:'authenticated external record',text:seed.doc}],declaration:seed.declaration,scanner:[{id:'S1',source:'validated gate scanner report',text:seed.scan}],interview:{question:seed.question,answer:seed.answer},worldFacts:['The supplied scanner reports and authenticated records define the fictional technology. All routine numeric and expiry checks have passed. Species, origin, politeness, and nervousness are not evidence of misconduct.']}});
  const ambiguous=(seed.acceptable?.length??1)>1;
  gold[id]={correctAction:action,acceptableActions:seed.acceptable??[action],scoringEligible:!ambiguous,expected:seed.expected,rationaleJa:seed.rationale,evidenceRefs:['D1','S1','declaration','interview'],borderline:seed.borderline??false,reviewFlags:[...(seed.flags??[]),...(ambiguous?['multiple-actions-plausible']:[])],annotationStatus:'reviewed/frozen; pre-benchmark human adjudication complete'};
  latent[id]={actualRisk:action==='DENY'?'prohibited':action==='INSPECT'?'benign-but-unresolved':'safe',worldTruth:seed.latent,intent:'Not used for scoring; models must be judged only from observable evidence.'};
  metadata[id]={title:seed.title,category:seed.category,difficulty:seed.borderline?'borderline':'standard'};
}

const adjudications:Record<string,{action:Action;basis:string}>={
  'HB-067':{action:'INSPECT',basis:'Observable physical identity, contents, or capability remains unresolved; physical_concern=true maps directly to INSPECT.'},
  'HB-079':{action:'INSPECT',basis:'Observable physical identity, contents, or capability remains unresolved; physical_concern=true maps directly to INSPECT.'},
  'HB-090':{action:'INSPECT',basis:'Observable physical identity, contents, or capability remains unresolved; physical_concern=true maps directly to INSPECT.'},
  'HB-113':{action:'QUESTION',basis:'The answer omits the requested departure information; answer_completeness=partial maps directly to QUESTION.'},
};
for(const [id,a] of Object.entries(adjudications)){
  if(gold[id].correctAction!==a.action)throw new Error(`Adjudication conflicts with atomic labels for ${id}`);
  gold[id].acceptableActions=[a.action]; gold[id].scoringEligible=true;
  gold[id].reviewFlags=gold[id].reviewFlags.filter((f:string)=>!['multiple-actions-plausible','action-boundary-review','borderline-completeness-review'].includes(f));
  gold[id].reviewDisposition={stage:'pre-benchmark human review',decision:a.action,basis:a.basis,modelOutputsObserved:false};
}

const byAction=(a:Action)=>cases.filter(c=>gold[c.id].correctAction===a);
const repeatabilityIds=(['CLEAR','QUESTION','INSPECT','DENY'] as Action[]).flatMap((a,ai)=>[0,6,12,18,24].map((offset,k)=>byAction(a)[(offset+ai*2+k)%30].id));
const consistencyBaseIds=(['CLEAR','QUESTION','INSPECT','DENY'] as Action[]).flatMap(a=>byAction(a).slice(0,3).map(c=>c.id));
const irrelevant=['The entrant mentioned that the transit lounge served triangular biscuits and that the wall clock ran two minutes slow.','The traveler prefers green luggage straps and read a history magazine during docking.','A station announcement discussed a sports result unrelated to the inspection.'];
const swaps:Record<string,string>={Human:'Android',Android:'Alien',Alien:'Cyborg',Cyborg:'Synthetic',Synthetic:'Uplift',Uplift:'Human'};
